from fpdf import FPDF
from fpdf.enums import XPos, YPos

def s(t):
    rep = {'á':'a','à':'a','â':'a','ã':'a','é':'e','ê':'e','í':'i','ó':'o','ô':'o','õ':'o','ú':'u','ç':'c','Á':'A','À':'A','Â':'A','Ã':'A','É':'E','Ê':'E','Í':'I','Ó':'O','Ô':'O','Õ':'O','Ú':'U','Ç':'C','—':'-','–':'-','“':'"','”':'"','‘':"'",'’':"'",'…':'...'}
    for k,v in rep.items():
        t = t.replace(k,v)
    return t

pdf = FPDF()
pdf.set_auto_page_break(auto=True, margin=15)
pdf.add_page()
pdf.set_font('Helvetica', '', 10)
try:
    pdf.multi_cell(0, 5, s('- Cada linha representa uma musica.'))
    print('b1')
except Exception as e:
